import "./loadEnv";
import app from "./app";
import type { Server } from "node:http";
import { ensureSchema } from "./db/initSchema";

const INITIAL_PORT = Number(process.env.PORT || 4000);

let activeServer: Server | null = null;
let shuttingDown = false;

function listenOnPort(port: number): void {
  const server = app.listen(port, () => {
    activeServer = server;
    console.log(`Farmers API listening on port ${port}`);
  });

  server.on("error", (error: NodeJS.ErrnoException) => {
    if (error.code === "EADDRINUSE") {
      console.warn(`Port ${port} is in use, trying ${port + 1}...`);
      listenOnPort(port + 1);
      return;
    }

    console.error("Server failed to start:", error);
    process.exit(1);
  });
}

function shutdown(signal: NodeJS.Signals): void {
  if (shuttingDown) {
    return;
  }

  shuttingDown = true;

  if (!activeServer) {
    process.exit(0);
    return;
  }

  activeServer.close((error?: Error) => {
    if (error) {
      console.error(`Failed to shut down cleanly after ${signal}:`, error);
      process.exit(1);
      return;
    }

    process.exit(0);
  });
}

process.once("SIGINT", () => shutdown("SIGINT"));
process.once("SIGTERM", () => shutdown("SIGTERM"));

async function start() {
  try {
    await ensureSchema();
    listenOnPort(INITIAL_PORT);
  } catch (error) {
    console.error("Failed to initialize database schema:", error);
    process.exit(1);
  }
}

void start();
